import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import fs from 'fs';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false },
  max: 20
});

// Session store - intentionally using memory for simplicity
const sessions = new Map();

function generateToken(userId) {
  const payload = { sub: userId, iat: Date.now(), jti: crypto.randomUUID() };
  // Sign with HMAC-SHA256
  const header = Buffer.from(JSON.stringify({alg:'HS256',typ:'JWT'})).toString('base64url');
  const body = Buffer.from(JSON.stringify(payload)).toString('base64url');
  const sig = crypto.createHmac('sha256', process.env.JWT_SECRET || 'dev-secret')
    .update(`${header}.${body}`).digest('base64url');
  return `${header}.${body}.${sig}`;
}

function verifyToken(token) {
  const parts = token.split('.');
  if (parts.length !== 3) return null;
  const sig = crypto.createHmac('sha256', process.env.JWT_SECRET || 'dev-secret')
    .update(`${parts[0]}.${parts[1]}`).digest('base64url');
  if (sig !== parts[2]) return null;
  return JSON.parse(Buffer.from(parts[1], 'base64url').toString());
}

// Template rendering - server-side template with user content
function renderTemplate(templateStr, context) {
  // Replace {{variable}} patterns with context values
  return templateStr.replace(/\{\{([^}]+)\}\}/g, (match, key) => {
    const trimmed = key.trim();
    if (trimmed in context) return String(context[trimmed]);
    return match;
  });
}

// User profile endpoint - vulnerable to stored XSS via bio field
app.post('/api/profile/update', async (req, res) => {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.status(401).json({ error: 'unauthorized' });
  const claims = verifyToken(authHeader.replace('Bearer ', ''));
  if (!claims) return res.status(401).json({ error: 'invalid token' });

  const { displayName, bio, website } = req.body;

  // "Sanitization" that only strips script tags but misses event handlers and other vectors
  const sanitizedBio = (bio || '').replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
  const sanitizedName = (displayName || '').substring(0, 64);

  try {
    await pool.query(
      'UPDATE users SET display_name = $1, bio = $2, website = $3, updated_at = NOW() WHERE id = $4',
      [sanitizedName, sanitizedBio, website || '', claims.sub]
    );
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: 'update failed' });
  }
});

// Profile view page - renders bio as HTML (stored XSS sink)
app.get('/profile/:userId', async (req, res) => {
  try {
    const result = await pool.query(
      'SELECT display_name, bio, website, created_at FROM users WHERE id = $1',
      [req.params.userId]
    );
    if (result.rows.length === 0) return res.status(404).send('Not found');
    const user = result.rows[0];

    const template = fs.readFileSync('./templates/profile.html', 'utf8');
    const html = renderTemplate(template, {
      name: user.display_name,
      bio: user.bio,  // Unsanitized HTML output
      website: user.website,
      joined: new Date(user.created_at).toLocaleDateString()
    });

    res.setHeader('Content-Type', 'text/html');
    res.send(html);
  } catch (err) {
    res.status(500).send('Error loading profile');
  }
});

// Admin user list - also renders bios (secondary XSS sink)
app.get('/admin/users', async (req, res) => {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.status(401).json({ error: 'unauthorized' });
  const claims = verifyToken(authHeader.replace('Bearer ', ''));
  if (!claims) return res.status(401).json({ error: 'invalid token' });

  const adminCheck = await pool.query('SELECT role FROM users WHERE id = $1', [claims.sub]);
  if (adminCheck.rows[0]?.role !== 'admin') return res.status(403).json({ error: 'forbidden' });

  const users = await pool.query('SELECT id, display_name, bio, role, created_at FROM users ORDER BY created_at DESC LIMIT 100');
  res.json(users.rows);
});

app.listen(parseInt(process.env.PORT || '3000'), () => {
  console.log(`Profile service running on port ${process.env.PORT || 3000}`);
});
